+    MODEL(Memory)
+    MODEL(Reduction)
+    MODEL(Scan)
+    MODEL(ControlFlow)
+    MODEL(IndexCast)
+    MODEL(Structural) MODEL(Deferred) MODEL(Rejected) MODEL(Dot)
+#undef MODEL
+  }
+  llvm_unreachable("unknown batch model");
+}
+llvm::StringRef getBatchAttributePolicyName(BatchAttributePolicy policy) {
+  switch (policy) {
+#define POLICY(value)                                                          \
+  case BatchAttributePolicy::value:                                            \
+    return #value;
+    POLICY(None)
+    POLICY(Constant)
+    POLICY(Axis)
+    POLICY(Range)
+    POLICY(Memory)
