+static OpFoldResult remap(OpFoldResult field,
+                          ConversionPatternRewriter &rewriter) {
+  if (auto value = dyn_cast<Value>(field)) {
+    Value mapped = rewriter.getRemappedValue(value);
+    return mapped ? OpFoldResult(mapped) : field;
+  }
+  return field;
+}
