-  for (size_t i = 0; i < srcShapeVals.size(); ++i) {
-    bool isDynamicDim = (i == static_cast<size_t>(dim) && readShape[i] == -1);
-    int64_t staticSize;
-
-    if (isDynamicDim) {
-      // Dynamic dimension: readShape[i] == -1 indicates dynamic
