-    int64_t staticStride = 1;
-    bool isDynamic = false;
-
-    // Check if stride needs to be dynamic (any dimension after i is dynamic)
-    for (size_t j = i + 1; j < srcShapeVals.size(); ++j) {
-      if (staticSizes[j] == ShapedType::kDynamic) {
-        isDynamic = true;
-        break;
-      }
