+  auto offset = mlir::triton::ptr::detail::materializeFullOffset(
+      info->offsets, builder.getI64Type(), builder,
+      outgoing.getOwner()->getLoc());
+  if (failed(offset))
+    return failure();
+  return ScalarPointerOffset{*offset, info->base == argument};
